class Instruction(Enum):
    """Piece instructions for rule sequences."""
    PAUSE   = 0
    DEFEND  = 1
    HARVEST = 2
    GIVE    = 3
    SETTLE  = 4  # settle or siege (reserved)
    FORWARD = 5
    ROT_L   = 6
    ROT_R   = 7

