@dataclass
class Squad:
    id: int = 0
    name: str = ""
    animal: str = ""
    pieces: list[Piece] = field(default_factory=list)
    flag: CountryFlag = None
    countryName:str = ""
    

    @classmethod
    def squads(cls,count=4,flag=None)->['Squad']:
        if flag is None:
    
            flag = CountryFlag.seaborn("husl", 1)[0]
        ret = []
        for animal, name in flag.country_squads(count):
            ret.append(Squad(name=name,animal=animal,flag=flag))
        return ret

    def __iter__(self): return iter(self.pieces)
    def __len__(self): return len(self.pieces)
    def __getitem__(self, i): return self.pieces[i]

    @property
    def alive(self) -> list[Piece]:
        return [p for p in self.pieces if p.health > 0]

    def by_rank(self) -> list[Piece]:
        """Pieces sorted by rank (king first) then lowest food."""
        return sorted(self.alive,
                      key=lambda p: (RANK_ORDER.get(p.piece_type, 99), p.food))

    def feed_turn(self, grid: HexGrid, elevations: np.ndarray,
                  food_tiers: np.ndarray):
        """Run one turn's food cycle for the whole squad.
        
        1. Harvest for anyone on HARVEST instruction
        2. Give phase (rank-ordered sharing)
        3. Eat phase — remove dead
        """
        for p in self.alive:
            if p.instructions.current == Instruction.HARVEST:
                harvest(p, grid, food_tiers)

        for p in self.by_rank():
            p.give(grid, elevations, self.pieces)

        self.pieces = [p for p in self.pieces if eat(p)]


