@dataclass
class BuildQueue:
    queue: List[int] = field(default_factory=list)  # PieceType enum values as ints
    progress: int = 0
    repeat: bool = False

    def encode(self) -> str:
        q = ','.join(str(x) for x in self.queue) if self.queue else ''
        return f"{q}|{self.progress}|{'1' if self.repeat else '0'}"

    @staticmethod
    def decode(s: str) -> 'BuildQueue':
        if not s:
            return BuildQueue()
        parts = s.split('|')
        queue = [int(x) for x in parts[0].split(',') if x] if parts[0] else []
        progress = int(parts[1]) if len(parts) > 1 and parts[1] else 0
        repeat = parts[2] not in ('0', '') if len(parts) > 2 else False
        return BuildQueue(queue=queue, progress=progress, repeat=repeat)


