@patch
def recruit(self: Settlement, piece_type: PieceType = PieceType.PAWN,
            location: int = None, flag: CountryFlag = None) -> Piece:
    # Birth year from settlement founding + 15–30, fallback to 1920s
    if self.founded and 1880 <= self.founded <= 2020:
        birth_year = self.founded + randint(15, 30)
    else:
        birth_year = randint(1920, 1928)

    # Random name from that era (both genders)
    try:
        all_names = (CountryFlag.commonNames(year=birth_year, gender="M") +
                     CountryFlag.commonNames(year=birth_year, gender="F"))
        name = random.choice(all_names)
    except (ValueError, IndexError):
        name = "Marvin"

    piece = Piece(
        owner_id=self.owner_id,
        settlement_id=self.id,
        location=location or self.location,
        piece_type=piece_type,
        name=name,
        birth_year=birth_year,
    )
    if flag:
        piece.flag = flag
    self.citizens.append(piece)
    return piece



