@patch
def piece_from_id(db: GameStorage, piece_id: str) -> Piece:
    row = db.pieces[piece_id]
    if row is None:
        raise KeyError(f"Piece {piece_id} not found")

    r = row if isinstance(row, dict) else asdict(row)
    rules_str = r.get('rules', '')
    rules = [int(x) for x in rules_str.split(',') if x] if rules_str else []

    return Piece(
        id=r['id'],
        owner_id=r['owner_id'],
        squad= r['squad'],
        name=r.get('name', 'Marvin'),
        birth_year=r.get('birth_year', 0),
        location=r['location'] if r['location'] >= 0 else None,
        size=r['size'],
        health=r['health'],
        max_health=r['max_health'],
        sight=r['sight'],
        movement_range=r['movement_range'],
        facing=r['facing'],
        instructions=InstructionList(
            rules, int(r.get('cursor', 0)), bool(r.get('patrol', 1))
        ),
        attack_strength=r['attack_strength'],
        move_strength=r['move_strength'],
        harvest_strength=r['harvest_strength'],
        scout_strength=r['scout_strength'],
        piece_type=PieceType(r['piece_type']) if r['piece_type'] else PieceType.PAWN,
        food=r.get('food', 0.0),
        diet=r.get('diet', 1.0),
        food_capacity=r.get('food_capacity', 10.0),
        harvest_goal=Resources(r['harvest_goal']) if r.get('harvest_goal') else None,
        settle_progress=r['settle_progress'],
        settle_threshold=r['settle_threshold'],
    )


